const SegmentPortAttachmentState_STATE_ATTACHED = "ATTACHED"
const SegmentPortAttachmentState_STATE_ATTACHED_PENDING_CONF = "ATTACHED_PENDING_CONF"
const SegmentPortAttachmentState_STATE_ATTACHED_IN_MOTION = "ATTACHED_IN_MOTION"
const SegmentPortAttachmentState_STATE_DETACHED = "DETACHED"

